import zlib from 'node:zlib';

export const SOURCE_ROW_COUNT = 1082;
export const UNIQUE_CANONICAL_COUNT = 1081;
export const NORMALIZATION_COLLISIONS = 1;

const GZIP_B64 = '';

export function loadBenchmarkRows() {
  const text = zlib.gunzipSync(Buffer.from(GZIP_B64, 'base64')).toString('utf8');
  return text.trim().split(/\r?\n/).map((line) => {
    const [item, tier = '', category = ''] = line.split('\t');
    return { item, tier, category };
  });
}
